a=p.parse_args()
rx=re.compile(a.g, re.I)
c=0
def texts(d):
    m=d.get('message') or {}
    cont=m.get('content')
    if isinstance(cont,str): yield cont; return
    for b in cont or []:
        if not isinstance(b,dict): continue
        if b.get('type')=='text': yield b.get('text','')
        elif b.get('type')=='tool_result':
            cc=b.get('content')
